contracts/LAIPBigInt3072.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title LAIPBigInt3072
 * @dev BigInteger library for 3072-bit LAIP operations
 * Uses EIP-198 modexp precompile for efficient large number arithmetic
 *
 * /// Lemnicoin is owner-sovereign.
 * /// Valid LAIP + Dilithium signatures define ownership.
 * /// Blockchains are execution venues only.
 *
 * This version supports 3072-bit keys for maximum quantum security.
 * 3072-bit = 384 bytes per coordinate
 *
 * Based on EIP-198: https://eips.ethereum.org/EIPS/eip-198
 * Precompile address: 0x0000000000000000000000000000000000000005
 */
library LAIPBigInt3072 {
    // EIP-198 modexp precompile address
    address constant MODEXP_PRECOMPILE = address(0x05);

    // Size constants for LAIP (3072-bit = 384 bytes)
    uint256 constant LAIP_BYTE_SIZE = 384;
    uint256 constant LAIP_BIT_SIZE = 3072;

    /**
     * @dev Modular exponentiation: (base^exponent) % modulus
     * Uses EIP-198 precompile for efficiency
     */
    function modExp(
        bytes memory base,
        bytes memory exponent,
        bytes memory modulus
    ) public view returns (bytes memory) {
        uint256 baseLen = base.length;
        uint256 expLen = exponent.length;
        uint256 modLen = modulus.length;

        require(modLen > 0, "LAIPBigInt3072: modulus cannot be zero");
        require(modLen <= LAIP_BYTE_SIZE, "LAIPBigInt3072: modulus too large");

        bytes memory input = abi.encodePacked(
            uint256(baseLen),
            uint256(expLen),
            uint256(modLen),
            base,
            exponent,
            modulus
        );

        bytes memory output = new bytes(modLen);
        bool success;

        assembly {
            success := staticcall(
                gas(),
                0x05,
                add(input, 0x20),
                mload(input),
                add(output, 0x20),
                modLen
            )
        }

        require(success, "LAIPBigInt3072: modexp precompile failed");
        return output;
    }

    /**
     * @dev Modular addition: (a + b) % modulus
     */
    function modAdd(
        bytes memory a,
        bytes memory b,
        bytes memory modulus
    ) public view returns (bytes memory) {
        uint256 L = modulus.length;
        require(L > 0 && L <= LAIP_BYTE_SIZE, "LAIPBigInt3072: bad modulus len");

        bytes memory p  = _toFixedLen(modulus, L);
        bytes memory aa = _canonicalizeOperand(a, p);
        bytes memory bb = _canonicalizeOperand(b, p);

        // low = (aa + bb) mod 2^k, carry = 0/1 indicating overflow past k bits
        (bytes memory low, uint256 carry) = _addFixedRaw(aa, bb);

        if (carry == 0) {
            // low is the true sum, just reduce if >= p
            if (_geFixed(low, p)) {
                low = _subFixed(low, p);
            }
            return low;
        }

        // carry==1 => true sum is (2^k + low).
        // Reduce once by subtracting p: (2^k + low) - p = low + (2^k - p).
        bytes memory delta = _negMod2k(p); // delta = 2^k - p as L bytes

        (bytes memory r, uint256 c2) = _addFixedRaw(low, delta);
        if (c2 == 1 || _geFixed(r, p)) {
            r = _subFixed(r, p);
        }
        return r;
    }

    function modSub(
        bytes memory a,
        bytes memory b,
        bytes memory modulus
    ) public view returns (bytes memory) {
        uint256 L = modulus.length;
        require(L > 0 && L <= LAIP_BYTE_SIZE, "LAIPBigInt3072: bad modulus len");

        bytes memory p  = _toFixedLen(modulus, L);
        bytes memory aa = _canonicalizeOperand(a, p);
        bytes memory bb = _canonicalizeOperand(b, p);

        if (_geFixed(aa, bb)) {
            return _subFixed(aa, bb);
        }

        // aa < bb => (aa - bb) mod p = p - (bb - aa)
        bytes memory diff = _subFixed(bb, aa);
        return _subFixed(p, diff);
    }

    // 2's complement in fixed width: returns (0 - x) mod 2^k = 2^k - x
    function _negMod2k(bytes memory x) private pure returns (bytes memory out) {
        uint256 L = x.length;
        out = new bytes(L);

        uint256 carry = 1;
        for (uint256 k = 0; k < L; k++) {
            uint256 i = L - 1 - k;
            uint256 inv = uint256(uint8(~x[i]));
            uint256 t = inv + carry;
            out[i] = bytes1(uint8(t & 0xFF));
            carry = t >> 8;
        }
    }

    function modMul(
        bytes memory a,
        bytes memory b,
        bytes memory modulus
    ) public view returns (bytes memory) {
        uint256 L = modulus.length;
        require(L > 0 && L <= LAIP_BYTE_SIZE, "LAIPBigInt3072: bad modulus len");

        // Canonicalize operands into field range
        bytes memory p  = _toFixedLen(modulus, L);
        bytes memory aa = _canonicalizeOperand(a, p);
        bytes memory bb = _canonicalizeOperand(b, p);

        // Use 2-squaring identity:
        // (a+b)^2 - (a-b)^2 = 4ab  =>  ab = ((a+b)^2 - (a-b)^2) / 4  (mod p)
        bytes memory sum = modAdd(aa, bb, modulus);
        bytes memory diff = modSub(aa, bb, modulus);

        bytes memory exp2 = hex"02";
        bytes memory sumSq  = modExp(sum,  exp2, modulus);
        bytes memory diffSq = modExp(diff, exp2, modulus);

        bytes memory fourAB = modSub(sumSq, diffSq, modulus);

        // divide by 4 = divide by 2 twice (mod prime)
        bytes memory half = _divBy2ModFixed(fourAB, modulus);
        bytes memory quarter = _divBy2ModFixed(half, modulus);

        return quarter;
    }

    function _canonicalizeOperand(bytes memory x, bytes memory modulus) private view returns (bytes memory) {
        bytes memory expOne = hex"01";
        return modExp(x, expOne, modulus);
    }

    // -------------------- helpers (fixed-width, no trimming) --------------------

    function _toFixedLen(bytes memory x, uint256 L) private pure returns (bytes memory out) {
        out = new bytes(L);
        if (x.length >= L) {
            // take least-significant L bytes (big-endian)
            uint256 off = x.length - L;
            for (uint256 i = 0; i < L; i++) out[i] = x[off + i];
        } else {
            // left pad
            uint256 off2 = L - x.length;
            for (uint256 i = 0; i < x.length; i++) out[off2 + i] = x[i];
        }
    }

    function _geFixed(bytes memory a, bytes memory b) private pure returns (bool) {
        for (uint256 i = 0; i < a.length; i++) {
            uint8 ai = uint8(a[i]);
            uint8 bi = uint8(b[i]);
            if (ai > bi) return true;
            if (ai < bi) return false;
        }
        return true; // equal
    }

    function _subFixed(bytes memory a, bytes memory b) private pure returns (bytes memory out) {
        uint256 L = a.length;
        out = new bytes(L);

        uint256 borrow = 0;
        for (uint256 k = 0; k < L; k++) {
            uint256 i = L - 1 - k;
            uint256 av = uint8(a[i]);
            uint256 bv = uint8(b[i]);

            uint256 subtrahend = bv + borrow;
            if (av >= subtrahend) {
                out[i] = bytes1(uint8(av - subtrahend));
                borrow = 0;
            } else {
                out[i] = bytes1(uint8(256 + av - subtrahend));
                borrow = 1;
            }
        }
    }

    function _addFixedRaw(bytes memory a, bytes memory b) private pure returns (bytes memory out, uint256 carry) {
        uint256 L = a.length;
        out = new bytes(L);

        uint256 c = 0;
        for (uint256 k = 0; k < L; k++) {
            uint256 i = L - 1 - k;
            uint256 sum = uint256(uint8(a[i])) + uint256(uint8(b[i])) + c;
            out[i] = bytes1(uint8(sum & 0xFF));
            c = sum >> 8;
        }
        carry = c;
    }

    function _divBy2ModFixed(bytes memory x, bytes memory modulus) private pure returns (bytes memory) {
        uint256 L = modulus.length;
        bytes memory xx = _toFixedLen(x, L);
        bytes memory mm = _toFixedLen(modulus, L);

        bool isEven = (uint8(xx[L - 1]) & 1) == 0;

        if (isEven) {
            return _rightShift1FixedWithTopBit(xx, 0);
        } else {
            (bytes memory s, uint256 carryByte) = _addFixedRaw(xx, mm);
            return _rightShift1FixedWithTopBit(s, uint8(carryByte));
        }
    }

    function _rightShift1FixedWithTopBit(bytes memory data, uint8 topBit) private pure returns (bytes memory out) {
        uint256 L = data.length;
        out = new bytes(L);

        uint8 carry = topBit & 1;

        for (uint256 i = 0; i < L; i++) {
            uint8 cur = uint8(data[i]);
            out[i] = bytes1((carry << 7) | (cur >> 1));
            carry = cur & 1;
        }
    }

    function _padLeft(bytes memory data, uint256 targetLen) private pure returns (bytes memory) {
        bytes memory padded = new bytes(targetLen);

        if (data.length >= targetLen) {
            uint256 srcOffset = data.length - targetLen;
            for (uint256 i = 0; i < targetLen; i++) {
                padded[i] = data[srcOffset + i];
            }
        } else {
            uint256 offset = targetLen - data.length;
            for (uint256 i = 0; i < data.length; i++) {
                padded[offset + i] = data[i];
            }
        }

        return padded;
    }

    function _trimLeadingZeros(bytes memory data) private pure returns (bytes memory) {
        uint256 firstNonZero = 0;
        while (firstNonZero < data.length && data[firstNonZero] == 0x00) {
            firstNonZero++;
        }

        if (firstNonZero == data.length) {
            bytes memory zero = new bytes(1);
            zero[0] = 0x00;
            return zero;
        }

        bytes memory trimmed = new bytes(data.length - firstNonZero);
        for (uint256 i = 0; i < trimmed.length; i++) {
            trimmed[i] = data[firstNonZero + i];
        }

        return trimmed;
    }

    function isZero(bytes memory data) public pure returns (bool) {
        for (uint256 i = 0; i < data.length; i++) {
            if (data[i] != 0) {
                return false;
            }
        }
        return true;
    }

    function eq(bytes memory a, bytes memory b) public pure returns (bool) {
        uint256 ia = 0;
        uint256 ib = 0;

        while (ia < a.length && a[ia] == 0) ia++;
        while (ib < b.length && b[ib] == 0) ib++;

        uint256 lenA = a.length - ia;
        uint256 lenB = b.length - ib;

        if (lenA != lenB) return false;

        for (uint256 i = 0; i < lenA; i++) {
            if (a[ia + i] != b[ib + i]) return false;
        }
        return true;
    }

    function toUint256(bytes memory data) public pure returns (uint256) {
        require(data.length <= 32, "LAIPBigInt3072: data too large for uint256");

        uint256 result = 0;
        for (uint256 i = 0; i < data.length; i++) {
            result = result * 256 + uint8(data[i]);
        }
        return result;
    }

    function fromUint256(uint256 value) public pure returns (bytes memory) {
        if (value == 0) {
            bytes memory zero = new bytes(1);
            zero[0] = 0x00;
            return zero;
        }

        uint256 temp = value;
        uint256 length = 0;
        while (temp > 0) {
            length++;
            temp >>= 8;
        }

        bytes memory result = new bytes(length);
        for (uint256 i = 0; i < length; i++) {
            result[length - 1 - i] = bytes1(uint8(value & 0xFF));
            value >>= 8;
        }

        return result;
    }
}

contracts/LAIPVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title LAIPVerifier (Stub)
 * @notice Simplified stub for backward compatibility
 * @dev Full LAIP verification has been moved off-chain to the Falcon attestation server.
 *      This stub provides type definitions and structural-only checks.
 *      For quantum-resistant transfers, use LemnicoinFalcon with Falcon attestation.
 */
library LAIPVerifier {
    // LAIP signature structure
    struct LAIPSignature {
        bytes Rx; // R point x-coordinate
        bytes Ry; // R point y-coordinate
        bytes s;  // Schnorr response
    }

    // LAIP public key structure
    struct LAIPPublicKey {
        bytes Qx;  // Public key point x-coordinate
        bytes Qy;  // Public key point y-coordinate
        bytes P0x; // Base point x-coordinate
        bytes P0y; // Base point y-coordinate
        bytes a;   // Domain parameter a
        bytes p;   // Domain parameter p (prime modulus)
        uint256 coordSize;
    }

    /**
     * @notice Decode packed bytes into LAIPSignature struct
     * @dev Format: Rx || Ry || s (coordSize*2 + sSize bytes)
     */
    function decodeSignature(bytes memory packed) internal pure returns (LAIPSignature memory) {
        // Detect coordinate size from packed length
        // 3072-bit: coordSize=384, packed = 384*2 + 417 = 1185
        // 2048-bit: coordSize=256, packed = 256*2 + 289 = 801
        // 1024-bit: coordSize=128, packed = 128*2 + 161 = 417

        uint256 coordSize;
        uint256 sSize;

        if (packed.length >= 1185) {
            coordSize = 384;
            sSize = packed.length - 768;
        } else if (packed.length >= 801) {
            coordSize = 256;
            sSize = packed.length - 512;
        } else if (packed.length >= 417) {
            coordSize = 128;
            sSize = packed.length - 256;
        } else {
            revert("LAIPVerifier: invalid signature length");
        }

        bytes memory Rx = new bytes(coordSize);
        bytes memory Ry = new bytes(coordSize);
        bytes memory s = new bytes(sSize);

        for (uint256 i = 0; i < coordSize; i++) {
            Rx[i] = packed[i];
            Ry[i] = packed[coordSize + i];
        }

        for (uint256 i = 0; i < sSize; i++) {
            s[i] = packed[coordSize * 2 + i];
        }

        return LAIPSignature({Rx: Rx, Ry: Ry, s: s});
    }

    /**
     * @notice Structural-only verification (format checks, no cryptographic verification)
     * @dev Use for binding when JS has already verified the full signature
     */
    function verifyStructuralOnly(
        LAIPSignature memory signature,
        LAIPPublicKey memory publicKey
    ) internal pure returns (bool) {
        // Check that signature components are non-empty
        if (signature.Rx.length == 0 || signature.Ry.length == 0 || signature.s.length == 0) {
            return false;
        }

        // Check that signature R coordinates match public key coordinate size
        uint256 coordSize = publicKey.coordSize;
        if (coordSize == 0) {
            coordSize = publicKey.Qx.length;
        }

        if (signature.Rx.length != coordSize || signature.Ry.length != coordSize) {
            return false;
        }

        // Check that public key has valid coordinates
        if (publicKey.Qx.length != coordSize || publicKey.Qy.length != coordSize) {
            return false;
        }

        return true;
    }

    /**
     * @notice Full verification (DEPRECATED - use Falcon attestation)
     * @dev For quantum-resistant transfers, use LemnicoinFalcon.transferWithFalconAttestation()
     *      On-chain LAIP verification has been moved to the EC2 attestation server.
     */
    function verify(
        LAIPSignature memory /* signature */,
        bytes memory /* message */,
        LAIPPublicKey memory /* publicKey */
    ) internal pure returns (bool) {
        // DEPRECATED: Full on-chain LAIP verification is no longer supported
        // Use the Falcon attestation system instead:
        // 1. Sign with LAIP + ML-DSA client-side
        // 2. Submit to EC2 attestor for verification
        // 3. Attestor signs with Falcon-512
        // 4. Submit Falcon attestation to LemnicoinFalcon contract
        revert("LAIPVerifier: use Falcon attestation for quantum-resistant transfers");
    }

    /**
     * @notice Lightweight verification (DEPRECATED)
     */
    function verifyLightweight(
        LAIPSignature memory /* signature */,
        LAIPPublicKey memory /* publicKey */
    ) internal pure returns (bool) {
        revert("LAIPVerifier: use Falcon attestation for quantum-resistant transfers");
    }
}

contracts/crypto/LAIPOnCurve.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../LAIPBigInt3072.sol";

library BigInt {
    struct Int {
        bytes value;
    }

    function fromBytes(bytes memory data) internal pure returns (Int memory) {
        return Int({value: data});
    }

    function mulMod(
        Int memory a,
        Int memory b,
        Int memory modulus
    ) internal view returns (Int memory) {
        return Int({value: LAIPBigInt3072.modMul(a.value, b.value, modulus.value)});
    }

    function addMod(
        Int memory a,
        Int memory b,
        Int memory modulus
    ) internal view returns (Int memory) {
        return Int({value: LAIPBigInt3072.modAdd(a.value, b.value, modulus.value)});
    }

    function eq(Int memory a, Int memory b) internal pure returns (bool) {
        return LAIPBigInt3072.eq(a.value, b.value);
    }
}

library LAIPOnCurve {
    using BigInt for BigInt.Int;

    struct LAIPPublicKey {
        bytes x;
        bytes y;
        bytes p;
        bytes a;
        bytes P0;
    }

    error LAIPOffCurve();

    function validate(LAIPPublicKey memory pk) internal view {
        if (!onCurve(pk)) {
            revert LAIPOffCurve();
        }
    }

    function onCurve(LAIPPublicKey memory pk) internal view returns (bool) {
        BigInt.Int memory x = BigInt.fromBytes(pk.x);
        BigInt.Int memory y = BigInt.fromBytes(pk.y);
        BigInt.Int memory p = BigInt.fromBytes(pk.p);
        BigInt.Int memory a = BigInt.fromBytes(pk.a);

        // Lemniscate curve: (x² + y²)² = a² * (x² - y²) (mod p)

        // x2 = x*x mod p
        BigInt.Int memory x2 = x.mulMod(x, p);

        // y2 = y*y mod p
        BigInt.Int memory y2 = y.mulMod(y, p);

        // Degenerate point check: reject if (x² + y²) ≡ 0 or x² = y²
        BigInt.Int memory sum = x2.addMod(y2, p);
        if (LAIPBigInt3072.isZero(sum.value)) {
            return false;
        }
        if (x2.eq(y2)) {
            return false;
        }

        // left = (x² + y²)²
        BigInt.Int memory left = sum.mulMod(sum, p);

        // right = a² * (x² - y²)
        BigInt.Int memory a2 = a.mulMod(a, p);
        BigInt.Int memory diff = BigInt.Int({value: LAIPBigInt3072.modSub(x2.value, y2.value, p.value)});
        BigInt.Int memory right = a2.mulMod(diff, p);

        return left.eq(right);
    }
}

contracts/diamond/Modifiers.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {AppStorage} from "./libraries/LibAppStorage.sol";
import {LibDiamond} from "./libraries/LibDiamond.sol";

error OnlyGuardian();
error OnlyCexGovernance();
error OnlyOwnerOrRekeyOperator();
error Paused();
error NotPaused();
error ReentrancyGuardReentrantCall();

// Reentrancy guard constants
uint256 constant _NOT_ENTERED = 1;
uint256 constant _ENTERED = 2;

/// @title Modifiers - Shared access-control modifiers for all Lemnicoin facets
/// @notice Every facet that needs AppStorage or access control should inherit this.
///         The first declared state variable is `AppStorage internal s` so that
///         all facets agree on the storage layout starting at slot 0.
contract Modifiers {
    AppStorage internal s;

    modifier onlyOwner() {
        LibDiamond.enforceIsContractOwner();
        _;
    }

    modifier onlyGuardian() {
        if (msg.sender != s.guardian) revert OnlyGuardian();
        _;
    }

    modifier onlyCexGovernance() {
        if (msg.sender != s.cexGovernanceSigner) revert OnlyCexGovernance();
        _;
    }

    /// @notice Allows either the diamond owner OR the dedicated rekey operator.
    ///         Used for attestor key rotation so automated rekey can continue
    ///         after ownership is transferred to a Gnosis Safe multisig.
    modifier onlyOwnerOrRekeyOperator() {
        if (msg.sender != LibDiamond.contractOwner() && msg.sender != s.rekeyOperator) {
            revert OnlyOwnerOrRekeyOperator();
        }
        _;
    }

    modifier whenNotPaused() {
        if (s.paused) revert Paused();
        _;
    }

    modifier whenPaused() {
        if (!s.paused) revert NotPaused();
        _;
    }

    /// @notice Prevents reentrancy attacks on functions that transfer ETH (M-04 fix)
    modifier nonReentrant() {
        // On first call, status is 0, which we treat as _NOT_ENTERED
        if (s.reentrancyStatus == _ENTERED) revert ReentrancyGuardReentrantCall();
        s.reentrancyStatus = _ENTERED;
        _;
        s.reentrancyStatus = _NOT_ENTERED;
    }
}

contracts/diamond/facets/KeyManagementFa.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {Modifiers} from "../Modifiers.sol";
import {AppStorage, QuantumKeys, QuantumKeyHashes, LibAppStorage} from "../libraries/LibAppStorage.sol";
import "../../LAIPVerifier.sol";
import "../../crypto/LAIPOnCurve.sol";

error KeysAlreadyBound();
error NoChallenge();
error InvalidDilithiumPKLength();
error QuantumKeysNotRegistered();
error LAIPQHashMismatch();
error LAIPCurveAlreadyValidated();
error KeysNotBound();
error OwnershipKeysImmutable();
error QuantumKeysImmutable();
error HolderFalconKeyImmutable();
error InvalidHolderFalconKey();

/// @title KeyManagementFacet — Quantum key binding, registration, and queries
/// @notice Handles createBindingChallenge, bindQuantumKeys, registerQuantumKeys,
///         and key query functions.
contract KeyManagementFacet is Modifiers {

    struct BindingInput {
        bytes laipQx;
        bytes laipQy;
        bytes laipP0x;
        bytes laipP0y;
        bytes laipA;
        bytes laipP;
        bytes dilithiumPubKey;
        bytes laipProof;
        bytes dilithiumProof;
    }

    event QuantumKeysBound(address indexed account, bytes32 laipPubKeyHash, bytes32 dilithiumPubKeyHash);
    event BindingChallengeCreated(address indexed account, bytes32 challenge);
    event QuantumKeysRegistered(address indexed user, bytes32 laipQHash, bytes32 laipP0Hash, bytes32 mldsaPkHash);
    event LAIPCurveValidated(address indexed account, bytes32 qHash);
    event LAIPCommitmentMigrated(address indexed account, bytes32 newCommitment);
    event HolderFalconKeyRegistered(address indexed account, bytes32 commitment);

    // =========================================================================
    // BINDING CHALLENGE
    // =========================================================================

    function createBindingChallenge() external returns (bytes32) {
        if (s.quantumKeys[msg.sender].bound) revert KeysAlreadyBound();

        bytes32 challenge = keccak256(
            abi.encodePacked(
                msg.sender,
                block.timestamp,
                blockhash(block.number - 1),
                block.prevrandao,
                block.basefee,
                s.challengeNonce++,
                gasleft()
            )
        );

        s.bindingChallenges[msg.sender] = challenge;
        emit BindingChallengeCreated(msg.sender, challenge);
        return challenge;
    }

    // =========================================================================
    // BIND QUANTUM KEYS
    // =========================================================================

    function bindQuantumKeys(BindingInput calldata input) external {
        if (s.quantumKeys[msg.sender].bound) revert KeysAlreadyBound();
        if (input.dilithiumPubKey.length != 2592) revert InvalidDilithiumPKLength();

        bytes32 challenge = s.bindingChallenges[msg.sender];
        if (challenge == bytes32(0)) revert NoChallenge();

        // Store LAIP public key
        s.quantumKeys[msg.sender].laip.Qx = input.laipQx;
        s.quantumKeys[msg.sender].laip.Qy = input.laipQy;
        s.quantumKeys[msg.sender].laip.P0x = input.laipP0x;
        s.quantumKeys[msg.sender].laip.P0y = input.laipP0y;
        s.quantumKeys[msg.sender].laip.a = input.laipA;
        s.quantumKeys[msg.sender].laip.p = input.laipP;

        // H-06: Fixed commitment encoding to include BOTH P0x and P0y
        // Previously only included P0x, which caused a mismatch with
        // registerQuantumKeysWithValidation (which uses full P0).
        // Now both paths produce: keccak256(Qx || Qy || P0x || P0y || a || p)
        s.laipKeyCommitment[msg.sender] = keccak256(
            abi.encodePacked(input.laipQx, input.laipQy, input.laipP0x, input.laipP0y, input.laipA, input.laipP)
        );

        // Verify proof structure
        _verifyBindingProofs(challenge, input);

        // Store Dilithium key and mark bound
        s.quantumKeys[msg.sender].dilithiumPublicKey = input.dilithiumPubKey;
        s.quantumKeys[msg.sender].bound = true;

        // Clear challenge
        delete s.bindingChallenges[msg.sender];

        emit QuantumKeysBound(
            msg.sender,
            keccak256(abi.encodePacked(input.laipQx, input.laipQy)),
            keccak256(input.dilithiumPubKey)
        );
    }

    // =========================================================================
    // HASH-BASED QUANTUM KEY REGISTRATION
    // =========================================================================

    function registerQuantumKeys(
        bytes32 laipQHash,
        bytes32 laipP0Hash,
        bytes32 mldsaPkHash
    ) external {
        _enforceKeyImmutability(laipQHash, laipP0Hash, mldsaPkHash);
        s.quantumKeyHashes[msg.sender] = QuantumKeyHashes({
            laipQHash: laipQHash,
            laipP0Hash: laipP0Hash,
            mldsaPkHash: mldsaPkHash,
            registered: true
        });
        emit QuantumKeysRegistered(msg.sender, laipQHash, laipP0Hash, mldsaPkHash);
    }

    /// @notice Register quantum keys AND validate LAIP curve in one transaction
    /// @dev Combines registerQuantumKeys + validateLaipCurve. Costs ~2.25M gas but
    ///      only requires one transaction. Use this for new key registration.
    /// @param laipQHash Hash of LAIP Q coordinates (keccak256(Qx || Qy))
    /// @param laipP0Hash Hash of LAIP P0 coordinates
    /// @param mldsaPkHash Hash of ML-DSA public key
    /// @param laipPk Full LAIP public key for curve validation
    function registerQuantumKeysWithValidation(
        bytes32 laipQHash,
        bytes32 laipP0Hash,
        bytes32 mldsaPkHash,
        LAIPOnCurve.LAIPPublicKey calldata laipPk
    ) external {
        _enforceKeyImmutability(laipQHash, laipP0Hash, mldsaPkHash);
        // Verify Q hash matches provided laipPk
        bytes32 computedQHash = keccak256(abi.encodePacked(laipPk.x, laipPk.y));
        if (computedQHash != laipQHash) revert LAIPQHashMismatch();

        // Register the keys
        s.quantumKeyHashes[msg.sender] = QuantumKeyHashes({
            laipQHash: laipQHash,
            laipP0Hash: laipP0Hash,
            mldsaPkHash: mldsaPkHash,
            registered: true
        });

        // Compute and store the LAIP key commitment (required for transfer verification)
        // Matches LibLemnicoin.requireLaipVerification: keccak256(x || y || P0 || a || p)
        s.laipKeyCommitment[msg.sender] = keccak256(
            abi.encodePacked(laipPk.x, laipPk.y, laipPk.P0, laipPk.a, laipPk.p)
        );

        // Perform expensive on-chain curve validation (~2.25M gas)
        // Validates: (x² + y²)² = a² * (x² - y²) mod p
        LAIPOnCurve.validate(laipPk);

        // Cache the validated Q hash
        s.laipValidatedQHash[msg.sender] = laipQHash;

        emit QuantumKeysRegistered(msg.sender, laipQHash, laipP0Hash, mldsaPkHash);
        emit LAIPCurveValidated(msg.sender, laipQHash);
    }

    /// @notice Register quantum keys with OFF-CHAIN curve validation (trusted)
    /// @dev Same as registerQuantumKeysWithValidation but skips expensive on-chain curve check.
    ///      Caller MUST validate Q is on curve off-chain before calling this.
    ///      Sets laipValidatedQHash so transfers work without on-chain validation.
    ///
    ///      H-02: RESTRICTED TO OWNER ONLY
    ///      This function skips on-chain curve validation and sets laipValidatedQHash
    ///      as if validation happened. Without access control, anyone could register
    ///      quantum keys bypassing the security check.
    ///
    /// @param laipQHash Hash of LAIP Q coordinates (keccak256(Qx || Qy))
    /// @param laipP0Hash Hash of LAIP P0 coordinates
    /// @param mldsaPkHash Hash of ML-DSA public key
    /// @param laipPk Full LAIP public key (used for commitment, not validated on-chain)
    function registerQuantumKeysTrusted(
        bytes32 laipQHash,
        bytes32 laipP0Hash,
        bytes32 mldsaPkHash,
        LAIPOnCurve.LAIPPublicKey calldata laipPk
    ) external onlyOwner {
        _enforceKeyImmutability(laipQHash, laipP0Hash, mldsaPkHash);
        // Verify Q hash matches provided laipPk
        bytes32 computedQHash = keccak256(abi.encodePacked(laipPk.x, laipPk.y));
        if (computedQHash != laipQHash) revert LAIPQHashMismatch();

        // Register the keys
        s.quantumKeyHashes[msg.sender] = QuantumKeyHashes({
            laipQHash: laipQHash,
            laipP0Hash: laipP0Hash,
            mldsaPkHash: mldsaPkHash,
            registered: true
        });

        // Compute and store the LAIP key commitment (required for transfer verification)
        s.laipKeyCommitment[msg.sender] = keccak256(
            abi.encodePacked(laipPk.x, laipPk.y, laipPk.P0, laipPk.a, laipPk.p)
        );

        // SKIP on-chain curve validation - caller validated off-chain
        // Trust that the dApp has verified Q is on the lemniscate curve
        s.laipValidatedQHash[msg.sender] = laipQHash;

        emit QuantumKeysRegistered(msg.sender, laipQHash, laipP0Hash, mldsaPkHash);
        emit LAIPCurveValidated(msg.sender, laipQHash);
    }

    /// @notice Register quantum key hashes + commitment for off-chain validated keys
    /// @dev Stores hashes, commitment, and sets laipValidatedQHash so transfers work.
    ///      Does NOT perform on-chain curve validation — caller MUST validate off-chain.
    ///      The Falcon attestation server verifies the curve before signing, so a user
    ///      with an invalid key cannot complete a transfer regardless.
    /// @param laipQHash Hash of LAIP Q coordinates (keccak256(Qx || Qy))
    /// @param laipP0Hash Hash of LAIP P0 coordinates
    /// @param mldsaPkHash Hash of ML-DSA public key
    /// @param laipCommitment Off-chain computed keccak256(Qx || Qy || P0 || a || p)
    function registerQuantumKeysOffChain(
        bytes32 laipQHash,
        bytes32 laipP0Hash,
        bytes32 mldsaPkHash,
        bytes32 laipCommitment
    ) external {
        _enforceKeyImmutability(laipQHash, laipP0Hash, mldsaPkHash);
        s.quantumKeyHashes[msg.sender] = QuantumKeyHashes({
            laipQHash: laipQHash,
            laipP0Hash: laipP0Hash,
            mldsaPkHash: mldsaPkHash,
            registered: true
        });

        s.laipKeyCommitment[msg.sender] = laipCommitment;
        s.laipValidatedQHash[msg.sender] = laipQHash;

        emit QuantumKeysRegistered(msg.sender, laipQHash, laipP0Hash, mldsaPkHash);
        emit LAIPCurveValidated(msg.sender, laipQHash);
    }

    // =========================================================================
    // HOLDER FALCON KEY (attestor-free signing path)
    // =========================================================================

    /// @notice Register the caller's OWN Falcon-512 key, so they can authorise transfers themselves
    ///         when the attestor is unreachable.
    /// @dev The key is derived in the dApp from the same 48-word seed as the LAIP and ML-DSA keys,
    ///      so there is nothing extra for the holder to store or back up.
    ///
    ///      Only a hash of the key is kept (one slot); the full 32-word key is supplied in calldata
    ///      at signing time and checked against this commitment.
    ///
    ///      IMMUTABLE once set — the same one-way ratchet as the other quantum keys. A stolen wallet
    ///      key therefore cannot replace the holder's Falcon key with the thief's own.
    /// @param ntth The Falcon public key in NTT domain, packed 16 coefficients per word.
    function registerHolderFalconKey(uint256[32] calldata ntth) external {
        bytes32 commitment = keccak256(abi.encodePacked(ntth));
        if (commitment == bytes32(0)) revert InvalidHolderFalconKey();

        bytes32 existing = s.holderFalconCommitment[msg.sender];
        // Re-registering the identical key is a no-op rather than a revert: the dApp derives the
        // key from the seed on every unlock and may race with itself across tabs.
        if (existing != bytes32(0)) {
            if (existing != commitment) revert HolderFalconKeyImmutable();
            return;
        }

        s.holderFalconCommitment[msg.sender] = commitment;
        emit HolderFalconKeyRegistered(msg.sender, commitment);
    }

    /// @notice The caller-supplied Falcon key commitment for `account`, or zero if none registered.
    /// @dev The dApp reads this at unlock to decide whether it still needs to register.
    function holderFalconCommitment(address account) external view returns (bytes32) {
        return s.holderFalconCommitment[account];
    }

    /// @notice Whether `account` can sign their own attestations if the attestor is unavailable.
    function hasHolderFalconKey(address account) external view returns (bool) {
        return s.holderFalconCommitment[account] != bytes32(0);
    }

    // =========================================================================
    // LAIP CURVE VALIDATION (separate transaction, ~2.25M gas)
    // =========================================================================

    /// @notice Validate LAIP public key is on the lemniscate curve (one-time, expensive)
    /// @dev Must be called before first quantumTransfer. Validates curve on-chain and
    ///      caches result. Subsequent transfers check the cache - unvalidated Q fails.
    /// @param laipPk The LAIP public key to validate
    function validateLaipCurve(
        LAIPOnCurve.LAIPPublicKey calldata laipPk
    ) external {
        // Verify quantum keys are registered
        if (!s.quantumKeyHashes[msg.sender].registered) revert QuantumKeysNotRegistered();

        // Compute Q hash and verify it matches registered laipQHash
        bytes32 qHash = keccak256(abi.encodePacked(laipPk.x, laipPk.y));
        if (s.quantumKeyHashes[msg.sender].laipQHash != qHash) revert LAIPQHashMismatch();

        // Check if already validated (save gas on redundant calls)
        if (s.laipValidatedQHash[msg.sender] == qHash) revert LAIPCurveAlreadyValidated();

        // Perform expensive on-chain curve validation (~2.25M gas)
        // Validates: (x² + y²)² = a² * (x² - y²) mod p
        LAIPOnCurve.validate(laipPk);

        // Cache the validated Q hash
        s.laipValidatedQHash[msg.sender] = qHash;

        emit LAIPCurveValidated(msg.sender, qHash);
    }

    /// @notice Check if an account's LAIP curve has been validated
    /// @param account The account to check
    /// @return validated True if curve validation has been completed
    /// @return qHash The validated Q hash (zero if not validated)
    function isLaipCurveValidated(address account) external view returns (bool validated, bytes32 qHash) {
        qHash = s.laipValidatedQHash[account];
        validated = qHash != bytes32(0);
    }

    // =========================================================================
    // MIGRATION: H-06 Commitment Format Update
    // =========================================================================

    /// @notice Migrate LAIP key commitment from old format to new format
    /// @dev For users who bound keys before H-06 fix. Old format used P0x only,
    ///      new format uses P0x || P0y to match registerQuantumKeysWithValidation.
    ///      This function recomputes the commitment using stored key data.
    ///
    ///      Old format: keccak256(Qx || Qy || P0x || a || p)
    ///      New format: keccak256(Qx || Qy || P0x || P0y || a || p)
    ///
    ///      Users must call this once to migrate, then dApp will work correctly.
    function migrateCommitmentFormat() external {
        // Only users who have already bound keys can migrate
        if (!s.quantumKeys[msg.sender].bound) revert KeysNotBound();

        // Retrieve stored LAIP key data
        LAIPVerifier.LAIPPublicKey storage laipKey = s.quantumKeys[msg.sender].laip;

        // Recompute commitment with NEW format (includes both P0x and P0y)
        bytes32 newCommitment = keccak256(
            abi.encodePacked(
                laipKey.Qx,
                laipKey.Qy,
                laipKey.P0x,
                laipKey.P0y,
                laipKey.a,
                laipKey.p
            )
        );

        // Update stored commitment
        s.laipKeyCommitment[msg.sender] = newCommitment;

        emit LAIPCommitmentMigrated(msg.sender, newCommitment);
    }

    // =========================================================================
    // V2: IMMUTABLE QUANTUM KEY REGISTRATION + BTC OWNERSHIP COMMITMENT
    // =========================================================================

    /// @notice Register V2 quantum keys with permanent ownership commitment (C_own).
    /// @dev Once ownershipCommitment is set for an address, it can NEVER be changed —
    ///      even by the wallet owner. This is the core theft-protection invariant:
    ///      an attacker who steals the wallet private key cannot re-register
    ///      different quantum keys or a different ownership commitment.
    ///      C_own = SHA-256(K_laip_public || K_dilithium_public || K_hashbased_public)
    ///      and serves as the cross-chain anchor for BTC wallet verification.
    /// @param laipQHash keccak256(Qx || Qy) — V2 LAIP public key hash
    /// @param laipP0Hash keccak256(P0x || P0y) — base point hash
    /// @param mldsaPkHash keccak256(dilithium_public_key) — ML-DSA-87 public key hash
    /// @param laipCommitment keccak256(Qx || Qy || P0 || a || p) — LAIP domain commitment
    /// @param ownershipCommitment C_own — SHA-256 of all three public key types
    function registerQuantumKeysV2(
        bytes32 laipQHash,
        bytes32 laipP0Hash,
        bytes32 mldsaPkHash,
        bytes32 laipCommitment,
        bytes32 ownershipCommitment
    ) external {
        // IMMUTABILITY: once C_own is set, keys can NEVER be changed. Before C_own is set,
        // an already-registered account may only re-assert the SAME key hashes (C2 fix).
        _enforceKeyImmutability(laipQHash, laipP0Hash, mldsaPkHash);

        s.quantumKeyHashes[msg.sender] = QuantumKeyHashes({
            laipQHash: laipQHash,
            laipP0Hash: laipP0Hash,
            mldsaPkHash: mldsaPkHash,
            registered: true
        });

        s.laipKeyCommitment[msg.sender] = laipCommitment;
        s.laipValidatedQHash[msg.sender] = laipQHash;
        s.ownershipCommitment[msg.sender] = ownershipCommitment;

        emit QuantumKeysRegistered(msg.sender, laipQHash, laipP0Hash, mldsaPkHash);
        emit LAIPCurveValidated(msg.sender, laipQHash);
    }

    // =========================================================================
    // VIEW FUNCTIONS
    // =========================================================================

    /// @notice Get the permanent ownership commitment for an account
    /// @return C_own (bytes32(0) if not yet registered via V2)
    function getOwnershipCommitment(address account) external view returns (bytes32) {
        return s.ownershipCommitment[account];
    }

    function hasQuantumKeys(address user) external view returns (bool) {
        return s.quantumKeyHashes[user].registered;
    }

    function getQuantumKeyHashes(address user) external view returns (
        bytes32 laipQHash, bytes32 laipP0Hash, bytes32 mldsaPkHash, bool registered
    ) {
        QuantumKeyHashes storage keys = s.quantumKeyHashes[user];
        return (keys.laipQHash, keys.laipP0Hash, keys.mldsaPkHash, keys.registered);
    }

    function getStoredLaipQx(address account) external view returns (bytes memory) {
        return s.quantumKeys[account].laip.Qx;
    }

    function laipKeyCommitment(address account) external view returns (bytes32) {
        return s.laipKeyCommitment[account];
    }

    function bindingChallenges(address account) external view returns (bytes32) {
        return s.bindingChallenges[account];
    }

    // =========================================================================
    // INTERNAL
    // =========================================================================

    /// @notice C2 fix: quantum keys are write-once per account.
    ///         Before the permanent ownership commitment (C_own) is set, format upgrades that
    ///         keep the SAME key material are allowed (matches the dApp's V1->V2 upgrade path);
    ///         changing the registered key hashes is rejected. Once C_own is set, registration is
    ///         fully immutable. This preserves theft-proofness — a stolen EVM key cannot re-point a
    ///         wallet's quantum keys — and blocks cloning another account's key hashes onto an
    ///         address that is already registered.
    function _enforceKeyImmutability(
        bytes32 newLaipQHash,
        bytes32 newLaipP0Hash,
        bytes32 newMldsaPkHash
    ) internal view {
        if (s.ownershipCommitment[msg.sender] != bytes32(0)) revert OwnershipKeysImmutable();
        QuantumKeyHashes storage existing = s.quantumKeyHashes[msg.sender];
        if (existing.registered) {
            if (existing.laipQHash != newLaipQHash ||
                existing.laipP0Hash != newLaipP0Hash ||
                existing.mldsaPkHash != newMldsaPkHash) {
                revert QuantumKeysImmutable();
            }
        }
    }

    function _verifyBindingProofs(bytes32 challenge, BindingInput calldata input) internal view {
        // Support both 2048-bit and 3072-bit LAIP proofs
        require(
            input.laipProof.length == 801 || input.laipProof.length == 1185,
            "Invalid LAIP proof length"
        );
        require(
            input.dilithiumProof.length >= 4500 && input.dilithiumProof.length <= 4700,
            "Invalid Dilithium proof length"
        );

        // Determine coordinate size from proof length
        uint256 coordSize;
        if (input.laipProof.length == 801) {
            coordSize = 256; // 2048-bit
        } else {
            coordSize = 384; // 3072-bit
        }

        // Verify public key coordinate lengths
        LAIPVerifier.LAIPPublicKey memory laipKey = s.quantumKeys[msg.sender].laip;
        require(
            laipKey.Qx.length == coordSize &&
            laipKey.Qy.length == coordSize &&
            laipKey.P0x.length == coordSize &&
            laipKey.P0y.length == coordSize &&
            laipKey.a.length == coordSize &&
            laipKey.p.length == coordSize,
            "LAIP public key size mismatch"
        );

        // Commitment structure validation
        bytes memory challengeBytes = abi.encodePacked(challenge);
        bytes32 commitment = keccak256(abi.encodePacked(input.laipProof, challengeBytes));
        commitment; // suppress unused warning
    }
}

contracts/diamond/interfaces/IDiamondCut.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

/// @title IDiamondCut - EIP-2535 Diamond Cut Interface
/// @notice Interface for adding, replacing, and removing facets and their functions
interface IDiamondCut {
    enum FacetCutAction {
        Add,
        Replace,
        Remove
    }

    struct FacetCut {
        address facetAddress;
        FacetCutAction action;
        bytes4[] functionSelectors;
    }

    /// @notice Add/replace/remove any number of functions and optionally execute a function with full access
    /// @param _diamondCut Contains the facet addresses and function selectors
    /// @param _init The address of the contract or facet to execute _calldata
    /// @param _calldata A function call, including function selector and arguments
    function diamondCut(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external;

    event DiamondCut(FacetCut[] _diamondCut, address _init, bytes _calldata);
}

contracts/diamond/libraries/LibAppStorag.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import "../../LAIPVerifier.sol";

/// @title LibAppStorage - Shared storage layout for Lemnicoin Diamond
/// @notice All facets share this single storage struct at slot 0.
///         NEVER reorder or remove fields — only append new fields at the end.
///         Changing field order will corrupt storage for deployed diamonds.

// =========================================================================
// STRUCT DEFINITIONS (used inside AppStorage mappings)
// =========================================================================

struct QuantumKeys {
    LAIPVerifier.LAIPPublicKey laip;
    bytes dilithiumPublicKey; // 2592 bytes
    bool bound;
}

struct QuantumKeyHashes {
    bytes32 laipQHash;      // keccak256(laipQx || laipQy)
    bytes32 laipP0Hash;     // keccak256(laipP0x || laipP0y)
    bytes32 mldsaPkHash;    // keccak256(mldsaPublicKey)
    bool registered;
}

struct VestingSchedule {
    uint256 totalAmount;
    uint256 unlocked;       // Not used — vesting calculated dynamically
    uint256 startTime;
    uint256 cliffDuration;
    uint256 vestingDuration;
}

struct PendingTransfer {
    address from;
    address to;
    uint256 amount;
    bytes32 txBodyHash;
    bytes dilithiumSignature;
    bytes laipSignature;
    uint256 feePaid;
    uint256 nonce;
    bool exists;
}

struct FalconEnvelope {
    bytes32 txHash;
    bytes32 laipPubKeyCommitment;
    bytes laipPublicKey;
    bytes laipSignature;
    bytes dilithiumSignature;
}

/// @notice Time-locked token grant that releases 100% at unlockDate
struct TimeLock {
    uint256 amount;
    uint256 unlockDate;
    bool active;
}

/// @notice M-of-N ring of holder Falcon keys governing one account ("Multi-Sig").
/// @dev Only keccak256 commitments of the member keys are stored (one slot each); the full
///      32-word NTT-domain keys travel in calldata at signing time and are checked against
///      these commitments, exactly like the single holderFalconCommitment.
struct RingConfig {
    bytes32[] memberCommitments; // keccak256(abi.encodePacked(uint256[32] ntth)) per member
    uint8 threshold;             // M — signatures required per operation
    bool registered;             // write-once ratchet, same as the other quantum keys
}

/// @notice LAIP-V3 quantum key registration (isogeny KEM curve + on-chain-verifiable SLH-DSA).
/// @dev Only hashes and a small parameter id live on chain; full keys travel in calldata at use
///      time and are checked against these commitments, exactly like the V1/V2 hashes.
struct LaipV3Keys {
    bytes32 curveHash;      // keccak256(enc(A_wallet)) — CSIDH public curve coefficient hash
    bytes32 slhdsaPkHash;   // keccak256(SLH-DSA-SHA2-128s public key) — the LOS/hash-based signer
    bytes32 mldsaPkHash;    // keccak256(ML-DSA-87 public key) — carried for C_own_v3 continuity
    bytes32 paramId;        // e.g. keccak256("laip-csidh-p1024") — versions the isogeny parameter set
    bool registered;        // write-once ratchet
}

// =========================================================================
// APP STORAGE — the single source of truth for all facets
// =========================================================================

struct AppStorage {
    // --- ERC20 ---
    mapping(address => uint256) balances;
    mapping(address => mapping(address => uint256)) allowances;
    uint256 totalSupply;
    string name;
    string symbol;

    // --- Pausable ---
    bool paused;

    // --- Access control ---
    address guardian;
    address cexGovernanceSigner;

    // --- Quantum key management ---
    mapping(address => QuantumKeys) quantumKeys;
    mapping(address => uint256) quantumNonce;
    mapping(address => bytes32) laipKeyCommitment;
    mapping(address => QuantumKeyHashes) quantumKeyHashes;
    mapping(address => bytes32) bindingChallenges;
    uint256 challengeNonce;

    // --- Dilithium verifier validation ---
    bool dilithiumVerifierValidated;
    bool dilithiumValidationGuardianApproval;

    // --- CEX whitelist ---
    mapping(address => bool) isWhitelistedCEX;
    bool cexBypassEnabled;
    bool pendingCexBypassState;
    uint256 pendingCexBypassEta;
    bool cexBypassGuardianApproval;
    bool cexBypassFuseActivated;
    address pendingCexGovernanceSigner;

    // --- Per-user CEX/DEX sessions ---
    mapping(address => mapping(address => uint256)) userCexSession;

    // --- Oracle ---
    address priceOracle;
    bool laipTransferEnabled;
    address pendingOracle;
    uint256 pendingOracleEta;
    bool oracleGuardianApproval;
    uint256 lastOracleUpdate;

    // --- External verifier references (DEPRECATED - C-01/C-02 audit) ---
    // These fields are kept for storage layout compatibility but are no longer used.
    // All transfers now use Falcon attestation via QuantumTransferFacet.
    address dualKeyVerifier;  // DEPRECATED: removed transferWithDualKeyProof
    address starkVerifier;    // DEPRECATED: removed transferWithStarkProof

    // --- Pending transfers ---
    mapping(bytes32 => PendingTransfer) pendingTransfers;

    // --- Deployment phase ---
    bool deploymentPhaseActive;
    mapping(address => VestingSchedule) vestingSchedules;

    // --- Falcon attestation (was FalconAttestation mixin) ---
    address falconVerifier;           // IZKNOXEthFalcon address
    uint256[32] attestorNtth;         // Attestor public key in NTT domain
    mapping(address => uint256) pqAttestationNonce;

    // --- Falcon governance (was FalconGovernance mixin) ---
    address governanceFalconVerifier; // IZKNOXEthFalcon address
    uint256[32] governanceAttestorNtth;
    bool governanceFalconInitialized;
    mapping(address => uint256) governanceNonce;

    // --- LAIP curve validation cache ---
    // Stores keccak256(x || y) after on-chain curve validation via validateLaipCurve().
    // Transfers check this cache - if Q not validated, transaction fails as forgery.
    mapping(address => bytes32) laipValidatedQHash;

    // --- Time-locked grants (added post-deployment) ---
    // Multiple time locks per beneficiary, indexed by lock ID
    mapping(address => mapping(uint256 => TimeLock)) timeLocks;
    mapping(address => uint256) timeLockCount;

    // --- Reentrancy guard (M-04 fix) ---
    uint256 reentrancyStatus;

    // --- DEX pool whitelist (always active, no toggle/fuse) ---
    // Whitelisted DEX pool/pair contracts can send LEMNI outbound (transfer)
    // and receive LEMNI inbound (transferFrom recipient check).
    // Security: LEMNI can only enter a pool through quantum-protected paths
    // (quantumApprove + transferFrom). approve() does NOT bypass for DEX pools.
    mapping(address => bool) isWhitelistedDEXPool;

    // --- Wallet whitelist (governance-controlled sender->recipient bypass) ---
    // Allows specific sender->recipient pairs to use transfer()/approve()
    // without quantum signatures. Enable/disable via 3-step governance.
    // Guardian can permanently disable via fuse.
    mapping(address => mapping(address => bool)) walletWhitelistPair;
    bool walletWhitelistEnabled;
    bool pendingWalletWhitelistState;
    bool pendingWalletWhitelistActive;
    bool walletWhitelistGuardianApproval;
    bool walletWhitelistFuseActivated;

    // --- Oracle disable/enable toggle ---
    // Stores the oracle address when fees are temporarily disabled via disablePriceOracle().
    // enablePriceOracle() restores priceOracle from this field.
    address savedPriceOracle;

    // --- Rekey operator (Safe migration support) ---
    // Dedicated address that can rotate attestor keys (with Falcon governance sig)
    // without needing to be the diamond owner. This allows automated key rotation
    // to continue after ownership is transferred to a Gnosis Safe multisig.
    address rekeyOperator;

    // --- Quantum-approved spender tracking ---
    // Set to true ONLY when quantumApprove() is called. transferFrom() checks
    // this to ensure the spender's allowance was set through the quantum-protected
    // path (Falcon attestation + LAIP verification), not via a pre-existing
    // allowance from the old approve() bypass bug.
    mapping(address => mapping(address => bool)) quantumApprovedSpender;

    // --- Circuit breaker (auto-pause on anomalous transfer volume) ---
    // Tracks rolling transfer volume in a time window. If cumulative volume
    // exceeds the threshold, the contract auto-pauses without governance action.
    // Normal unpause governance flow (owner + Falcon) resumes operations.
    uint256 circuitBreakerWindowStart;   // start timestamp of current window
    uint256 circuitBreakerWindowVolume;  // cumulative transfer volume in current window
    uint256 circuitBreakerThreshold;     // max volume before auto-pause (0 = disabled)
    uint256 circuitBreakerWindow;        // window duration in seconds (e.g., 3600 = 1 hour)

    // --- Circuit breaker exclusions (liquidity infrastructure) ---
    // Transfers where either `from` or `to` is in this set are NOT counted
    // toward circuit breaker volume. Typical entries: deployer wallet,
    // Uniswap router, NonfungiblePositionManager, pool addresses.
    mapping(address => bool) circuitBreakerExcluded;

    // --- V2 Ownership Commitment (BTC cross-chain anchor) ---
    // C_own = SHA-256(K_laip_public || K_dilithium_public || K_hashbased_public)
    // Once set (non-zero), CANNOT be changed — even by the wallet owner.
    // This is the core theft-protection invariant: an attacker who steals
    // the wallet private key cannot re-register different quantum keys.
    // Also serves as the cross-chain anchor for BTC wallet verification.
    mapping(address => bytes32) ownershipCommitment;

    // --- Holder Falcon key (attestor-free signing path) ---
    // keccak256(abi.encodePacked(uint256[32] ntth)) for the holder's OWN Falcon-512 key, derived
    // in the dApp from the same 48-word seed as their LAIP and ML-DSA keys. When the attestor
    // cannot be reached, the holder signs the identical attestation packet themselves and passes
    // the full ntth in calldata; the chain hashes it and compares against this commitment.
    //
    // Storing only the hash keeps registration to one slot. Set once and then IMMUTABLE — the same
    // one-way ratchet as the other quantum keys, so a stolen wallet key cannot swap in a new one.
    //
    // NOTE: appended at the END of AppStorage. Diamond storage is layout-sensitive; new fields must
    // only ever be added here, never inserted above.
    mapping(address => bytes32) holderFalconCommitment;

    // --- Attestor liveness gate (holder-only path time-lock) ---
    // The single-signature holder-only path (quantumTransferWithHolderKey) is an escape hatch for
    // when the attestor is unreachable. To make normal operation a TRUE 2-of-2, that path is kept
    // CLOSED while the attestor proves it is alive, and only OPENS after the attestor has been
    // silent for `holderOnlyOutageBlocks` blocks.
    //
    //   attestorHeartbeatSigner   — the EOA the attestor service uses to post heartbeats. Set by
    //                               the owner. Distinct from the attestor's Falcon key (attestorNtth)
    //                               so heartbeating never touches the signing key.
    //   attestorLastHeartbeatBlock — block.number of the most recent heartbeat.
    //   holderOnlyOutageBlocks     — N. If 0 the gate is DISABLED and the holder-only path is always
    //                               allowed (exactly the pre-upgrade behavior), so this upgrade is
    //                               non-breaking until the owner configures it.
    //
    // Appended at the END — never insert above this.
    address attestorHeartbeatSigner;
    uint256 attestorLastHeartbeatBlock;
    uint256 holderOnlyOutageBlocks;

    // --- Multi-Sig rings (M-of-N holder Falcon multisig) ---
    // A ring account's balance moves only with >= threshold member Falcon signatures over the same
    // EIP-712 digest, plus the attestor's signature while the attestor is provably live (the same
    // liveness gate the holder-only path uses). Ring accounts have their single-signature paths
    // (dual / holder-only / session / recovery) closed in LibLemnicoin.requireDualFalcon and
    // transferWithHolderFalconAttestationFrom.
    //
    //   ringConfig          — the write-once ring definition per account.
    //   ringBypassNonce     — replay protection for bypass declarations/cancellations.
    //   ringBypassMaturesAt — timestamp an M-signed "proceed without the attestor" declaration
    //                         matures (0 = none active). The escape for an attestor that heartbeats
    //                         but refuses to co-sign; guarantees a ring is never frozen by us.
    //   ringBypassDelaySeconds — owner-set maturation delay (0 = use the 7-day default).
    //
    // Appended at the END — never insert above this.
    mapping(address => RingConfig) ringConfig;
    mapping(address => uint256) ringBypassNonce;
    mapping(address => uint256) ringBypassMaturesAt;
    uint256 ringBypassDelaySeconds;

    // --- LAIP-V3: isogeny KEM + hash-based (LOS/SLH-DSA) quantum keys ---
    // V3 is strictly ADDITIVE. Legacy V1/V2 registration (quantumKeyHashes, ownershipCommitment,
    // laipKeyCommitment) is preserved untouched, so a V3-migrated wallet can ALWAYS still transact
    // on its existing V1/V2 + dual-Falcon path — funds are never frozen by adopting V3.
    //
    //   laipV3          — per-account V3 key registration (see LaipV3Keys). Write-once ratchet.
    //   ownershipCommitmentV3 — C_own_v3 = keccak256(curveHash || mldsaPkHash || slhdsaPkHash),
    //                           the V3 hash-based-inclusive ownership anchor. Legacy `ownershipCommitment`
    //                           (the BTC cross-chain anchor) is DELIBERATELY left in place and readable
    //                           forever; BTC tooling adopts C_own_v3 on its own schedule.
    //
    // Appended at the END — never insert above this.
    mapping(address => LaipV3Keys) laipV3;
    mapping(address => bytes32) ownershipCommitmentV3;

    // Controls whether the on-chain SLH-DSA (LOS / hash family) is REQUIRED on the attestor-independent
    // path. Default false = STRICT: every such transfer must present a valid SLH signature that verifies
    // on chain, or it reverts — so the transfer always requires Falcon AND the hash family (immune to a
    // Falcon/lattice break). Owner sets this true ONLY on a chain whose blocks genuinely cannot fit the
    // ~24.6M-gas verification; there the path relaxes to best-effort/Falcon-only. This is a deliberate
    // per-chain governance decision, NOT an attacker-triggerable per-transaction skip.
    bool laipV3RelaxSlh;

    // Address of the external SlhDsaVerifier contract, called with a bounded gas budget so an
    // out-of-gas in the ~24.6M verification is caught and the transfer proceeds on Falcon. If zero,
    // the on-chain SLH-DSA check is skipped entirely (Falcon-only). Set by the owner post-deploy.
    address slhDsaVerifier;

    // --- LAIP-V3 ECONOMIC SLH EXEMPTION (the "1% rule") ---
    // A strict on-chain SLH-DSA verify costs ~24.6M gas. On a small transfer that gas can be worth
    // more than the value being moved, so the holder is made to pay more for the hash-family factor
    // than the factor protects. When that is true the factor is dropped and the transfer proceeds on
    // the Falcon floor.
    //
    // The rule is deliberately gated by an ORACLE-INDEPENDENT ceiling, because the value half of the
    // comparison comes from PriceOracle, whose LEMNI leg is a Uniswap V3 SPOT price and is therefore
    // manipulable inside a single block. The ceiling means no amount of price manipulation, and no
    // amount of basefee inflation, can widen the exemption past a fixed number of LEMNI per window.
    //
    //   slhExemptMaxAmount   — EXPLICIT governance ceiling, in LEMNI wei, on (a) any single exempt
    //                          transfer and (b) the rolling per-account total moved without on-chain
    //                          SLH. 0 = use the self-calibrating default (see LibSlhEconomics
    //                          .effectiveCeiling): the break-even amount under the live oracle,
    //                          clamped by totalSupply / DEFAULT_SUPPLY_DIVISOR so a manipulated
    //                          price cannot widen it. The rule is therefore ON by default.
    //   slhExemptDisabled    — governance kill switch for the whole economic exemption. false by
    //                          default, i.e. the rule is active. Setting it true restores the
    //                          pre-1%-rule behaviour: SLH required wherever the chain fits it.
    //   slhExemptWindow      — length of the rolling window in seconds. 0 = 1 day.
    //   slhExemptWindowStart — per-account start of the current window.
    //   slhExemptUsed        — per-account LEMNI wei moved without on-chain SLH in the current window.
    //
    // Appended at the END — never insert above this.
    uint256 slhExemptMaxAmount;
    uint256 slhExemptWindow;
    mapping(address => uint256) slhExemptWindowStart;
    mapping(address => uint256) slhExemptUsed;
    bool slhExemptDisabled;

    // --- Protocol fee exemption (per-wallet, governance-controlled) ---
    // Wallets in this set pay NO native protocol fee (the 12-40 bps collected in native
    // POL/ETH as msg.value) on ANY quantum transfer/approve/recovery path. This is the
    // blanket per-wallet counterpart to the pair-based walletWhitelist: it only ever SKIPS
    // the fee, never gates a transfer, so it can never freeze funds. Defaults to false for
    // every address (non-breaking). Managed by the owner via FeeExemptionFacet.setFeeExempt.
    //
    // SECURITY NOTE: the fee is protocol REVENUE, not a fund-safety control. Exempting a
    // wallet costs the protocol fee income on that wallet's transfers and nothing more; it
    // cannot be used to move another account's funds or bypass any quantum signature.
    //
    // Appended at the END — never insert above this.
    mapping(address => bool) feeExempt;

    // --- Circuit breaker: count each token once per window ---
    // Tokens a wallet RECEIVED in a counted transfer during the current breaker window were
    // already counted when they moved. When that wallet sends them on (onward, back, or
    // around a ring of wallets) they are not counted again, so cycling LEMNI between wallets
    // can never add more to the window volume than the tokens actually moved.
    // cbReceivedWindow[a] is the window start the cbReceived[a] figure belongs to; any other
    // value means "nothing received this window" (stale entries are ignored, never cleared).
    // Appended at the END — never insert above this.
    mapping(address => uint256) cbReceivedWindow;
    mapping(address => uint256) cbReceived;
}

// =========================================================================
// CONSTANTS (not stored — compiled into bytecode)
// =========================================================================

uint256 constant MAX_SUPPLY = 1_000_000_000 * 10 ** 18;

// Session duration limits (audit fix #6: reduced from 24h to 4h to limit exposure window)
// SECURITY: Even with a valid session, attackers only have a 4-hour window if they
// compromise a session. Users should create sessions only when actively trading.
uint256 constant MAX_SESSION_DURATION = 4 hours;
uint256 constant MIN_SESSION_DURATION = 5 minutes;

uint256 constant ORACLE_UPDATE_DELAY = 1 days;
uint256 constant ORACLE_UPDATE_COOLDOWN = 1 hours;

// CEX bypass requires 1-day timelock + guardian approval (defense in depth)
// SECURITY: cexBypassEnabled defaults to false. Once cexBypassFuseActivated is set,
// CEX bypass can NEVER be re-enabled (permanent shutdown via guardian fuse).
uint256 constant CEX_BYPASS_DELAY = 1 days;

uint256 constant PENDING_TRANSFER_TIMEOUT = 100;

library LibAppStorage {
    /// @notice Returns the AppStorage struct at slot 0.
    ///         All facets MUST use this (or declare `AppStorage internal s;`
    ///         as their first state variable) so they agree on layout.
    function appStorage() internal pure returns (AppStorage storage s) {
        assembly {
            s.slot := 0
        }
    }
}

contracts/diamond/libraries/LibDiamond.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import "../interfaces/IDiamondCut.sol";

error InitializationFunctionReverted(address _initializationContractAddress, bytes _calldata);
error NotDiamondOwner();
error NoSelectorsInFacetCut();
error FunctionAlreadyExists(bytes4 selector);
error FunctionDoesNotExist(bytes4 selector);
error FacetAddressIsZero();
error FacetAddressIsNotZero();
error FacetHasNoCode(address facet);
error IncorrectFacetCutAction();

/// @title LibDiamond - Core diamond proxy storage and logic
/// @notice Stores facet-to-selector mappings at a keccak256 slot,
///         separate from AppStorage at slot 0.
library LibDiamond {
    bytes32 constant DIAMOND_STORAGE_POSITION = keccak256("diamond.standard.diamond.storage");

    struct FacetAddressAndPosition {
        address facetAddress;
        uint96 functionSelectorPosition; // position in facetFunctionSelectors.functionSelectors array
    }

    struct FacetFunctionSelectors {
        bytes4[] functionSelectors;
        uint256 facetAddressPosition; // position in facetAddresses array
    }

    struct DiamondStorage {
        // maps function selector to the facet address and
        // the position of the selector in the facetFunctionSelectors.functionSelectors array
        mapping(bytes4 => FacetAddressAndPosition) selectorToFacetAndPosition;
        // maps facet addresses to function selectors
        mapping(address => FacetFunctionSelectors) facetFunctionSelectors;
        // facet addresses
        address[] facetAddresses;
        // Used to query if a contract implements an interface.
        // Used to implement ERC-165.
        mapping(bytes4 => bool) supportedInterfaces;
        // owner of the contract
        address contractOwner;
    }

    event DiamondCut(IDiamondCut.FacetCut[] _diamondCut, address _init, bytes _calldata);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    function diamondStorage() internal pure returns (DiamondStorage storage ds) {
        bytes32 position = DIAMOND_STORAGE_POSITION;
        assembly {
            ds.slot := position
        }
    }

    function setContractOwner(address _newOwner) internal {
        DiamondStorage storage ds = diamondStorage();
        address previousOwner = ds.contractOwner;
        ds.contractOwner = _newOwner;
        emit OwnershipTransferred(previousOwner, _newOwner);
    }

    function contractOwner() internal view returns (address contractOwner_) {
        contractOwner_ = diamondStorage().contractOwner;
    }

    function enforceIsContractOwner() internal view {
        if (msg.sender != diamondStorage().contractOwner) {
            revert NotDiamondOwner();
        }
    }

    // Internal function version of diamondCut
    function diamondCut(
        IDiamondCut.FacetCut[] memory _diamondCut,
        address _init,
        bytes memory _calldata
    ) internal {
        for (uint256 facetIndex; facetIndex < _diamondCut.length; facetIndex++) {
            IDiamondCut.FacetCutAction action = _diamondCut[facetIndex].action;
            if (action == IDiamondCut.FacetCutAction.Add) {
                addFunctions(
                    _diamondCut[facetIndex].facetAddress,
                    _diamondCut[facetIndex].functionSelectors
                );
            } else if (action == IDiamondCut.FacetCutAction.Replace) {
                replaceFunctions(
                    _diamondCut[facetIndex].facetAddress,
                    _diamondCut[facetIndex].functionSelectors
                );
            } else if (action == IDiamondCut.FacetCutAction.Remove) {
                removeFunctions(
                    _diamondCut[facetIndex].facetAddress,
                    _diamondCut[facetIndex].functionSelectors
                );
            } else {
                revert IncorrectFacetCutAction();
            }
        }
        emit DiamondCut(_diamondCut, _init, _calldata);
        initializeDiamondCut(_init, _calldata);
    }

    function addFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        if (_functionSelectors.length == 0) revert NoSelectorsInFacetCut();
        DiamondStorage storage ds = diamondStorage();
        if (_facetAddress == address(0)) revert FacetAddressIsZero();
        uint96 selectorPosition = uint96(
            ds.facetFunctionSelectors[_facetAddress].functionSelectors.length
        );
        // add new facet address if it does not exist
        if (selectorPosition == 0) {
            addFacet(ds, _facetAddress);
        }
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds
                .selectorToFacetAndPosition[selector]
                .facetAddress;
            if (oldFacetAddress != address(0)) revert FunctionAlreadyExists(selector);
            addFunction(ds, selector, selectorPosition, _facetAddress);
            selectorPosition++;
        }
    }

    function replaceFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        if (_functionSelectors.length == 0) revert NoSelectorsInFacetCut();
        DiamondStorage storage ds = diamondStorage();
        if (_facetAddress == address(0)) revert FacetAddressIsZero();
        uint96 selectorPosition = uint96(
            ds.facetFunctionSelectors[_facetAddress].functionSelectors.length
        );
        // add new facet address if it does not exist
        if (selectorPosition == 0) {
            addFacet(ds, _facetAddress);
        }
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds
                .selectorToFacetAndPosition[selector]
                .facetAddress;
            if (oldFacetAddress == _facetAddress) {
                revert FunctionAlreadyExists(selector);
            }
            if (oldFacetAddress == address(0)) revert FunctionDoesNotExist(selector);
            removeFunction(ds, oldFacetAddress, selector);
            addFunction(ds, selector, selectorPosition, _facetAddress);
            selectorPosition++;
        }
    }

    function removeFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        if (_functionSelectors.length == 0) revert NoSelectorsInFacetCut();
        DiamondStorage storage ds = diamondStorage();
        // _facetAddress must be address(0) for Remove action
        if (_facetAddress != address(0)) revert FacetAddressIsNotZero();
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds
                .selectorToFacetAndPosition[selector]
                .facetAddress;
            if (oldFacetAddress == address(0)) revert FunctionDoesNotExist(selector);
            removeFunction(ds, oldFacetAddress, selector);
        }
    }

    function addFacet(DiamondStorage storage ds, address _facetAddress) internal {
        enforceHasContractCode(_facetAddress);
        ds.facetFunctionSelectors[_facetAddress].facetAddressPosition = ds
            .facetAddresses
            .length;
        ds.facetAddresses.push(_facetAddress);
    }

    function addFunction(
        DiamondStorage storage ds,
        bytes4 _selector,
        uint96 _selectorPosition,
        address _facetAddress
    ) internal {
        ds
            .selectorToFacetAndPosition[_selector]
            .functionSelectorPosition = _selectorPosition;
        ds.selectorToFacetAndPosition[_selector].facetAddress = _facetAddress;
        ds
            .facetFunctionSelectors[_facetAddress]
            .functionSelectors
            .push(_selector);
    }

    function removeFunction(
        DiamondStorage storage ds,
        address _facetAddress,
        bytes4 _selector
    ) internal {
        // get selector position in array
        uint256 selectorPosition = ds
            .selectorToFacetAndPosition[_selector]
            .functionSelectorPosition;
        uint256 lastSelectorPosition = ds
            .facetFunctionSelectors[_facetAddress]
            .functionSelectors
            .length - 1;
        // if not the last selector, swap with last and pop
        if (selectorPosition != lastSelectorPosition) {
            bytes4 lastSelector = ds
                .facetFunctionSelectors[_facetAddress]
                .functionSelectors[lastSelectorPosition];
            ds.facetFunctionSelectors[_facetAddress].functionSelectors[
                    selectorPosition
                ] = lastSelector;
            ds
                .selectorToFacetAndPosition[lastSelector]
                .functionSelectorPosition = uint96(selectorPosition);
        }
        // delete the last selector
        ds.facetFunctionSelectors[_facetAddress].functionSelectors.pop();
        delete ds.selectorToFacetAndPosition[_selector];

        // if no more selectors for facet address then delete the facet address
        if (lastSelectorPosition == 0) {
            // replace facet address with last facet address and delete last facet address
            uint256 lastFacetAddressPosition = ds.facetAddresses.length - 1;
            uint256 facetAddressPosition = ds
                .facetFunctionSelectors[_facetAddress]
                .facetAddressPosition;
            if (facetAddressPosition != lastFacetAddressPosition) {
                address lastFacetAddress = ds.facetAddresses[
                    lastFacetAddressPosition
                ];
                ds.facetAddresses[facetAddressPosition] = lastFacetAddress;
                ds
                    .facetFunctionSelectors[lastFacetAddress]
                    .facetAddressPosition = facetAddressPosition;
            }
            ds.facetAddresses.pop();
            delete ds
                .facetFunctionSelectors[_facetAddress]
                .facetAddressPosition;
        }
    }

    function initializeDiamondCut(address _init, bytes memory _calldata) internal {
        if (_init == address(0)) {
            return;
        }
        enforceHasContractCode(_init);
        (bool success, bytes memory error) = _init.delegatecall(_calldata);
        if (!success) {
            if (error.length > 0) {
                // bubble up error
                assembly {
                    let returndata_size := mload(error)
                    revert(add(32, error), returndata_size)
                }
            } else {
                revert InitializationFunctionReverted(_init, _calldata);
            }
        }
    }

    function enforceHasContractCode(address _contract) internal view {
        uint256 contractSize;
        assembly {
            contractSize := extcodesize(_contract)
        }
        if (contractSize == 0) revert FacetHasNoCode(_contract);
    }
}
